// priority: 3
// Claim allowance = base + chunks of the milestone quests the party has completed in its own faction chapter.
// Generated by automation/faction-milestones; see README.md#faction-milestones.
const MilestoneQuestFile = Java.loadClass('dev.ftb.mods.ftbquests.quest.ServerQuestFile');
const MilestoneTeams = Java.loadClass('dev.ftb.mods.ftbteams.api.FTBTeamsAPI');
const MilestoneChunks = Java.loadClass('dev.ftb.mods.ftbchunks.api.FTBChunksAPI');

const factionMilestones = {
  config: (() => {
    let data = JSON.parse(JsonIO.readString('kubejs/config/faction_milestones.json'));
    let hex = /^[0-9A-F]{16}$/;
    let whole = value => typeof value === 'number' && Math.floor(value) === value;
    if (!data || data.version !== 1 || !whole(data.baseClaims) || data.baseClaims < 0
      || !whole(data.maxClaims) || data.maxClaims < data.baseClaims || !data.factions || !data.rewards) {
      throw new Error('Invalid faction_milestones.json');
    }
    Object.keys(data.factions).forEach(id => {
      let faction = data.factions[id];
      if (!factionDefinitions.factions.some(entry => entry.id === id)) throw new Error('Unknown milestone faction ' + id);
      if (![faction.chapter, faction.charterQuest, faction.charterTask, faction.homeTask].every(value => hex.test(value))) {
        throw new Error('Invalid milestone IDs for ' + id);
      }
      let total = 0;
      Object.keys(faction.quests).forEach(quest => {
        if (!hex.test(quest) || !whole(faction.quests[quest]) || faction.quests[quest] < 1) throw new Error('Invalid milestone quest ' + quest);
        total += faction.quests[quest];
      });
      if (total > data.maxClaims - data.baseClaims) throw new Error('Milestones for ' + id + ' exceed the claim cap');
    });
    return data;
  })(),

  file() { return MilestoneQuestFile.INSTANCE; },
  ready() { return !!this.file(); },
  teams() { return MilestoneTeams.api().getManager(); },

  // Quest IDs exceed JS number precision, so they are only ever compared as FTB's hex strings.
  chapterQuests(faction) {
    let wanted = this.config.factions[faction].chapter;
    let result = [];
    this.file().getAllChapters().forEach(chapter => {
      if (String(chapter.getCodeString()) === wanted) chapter.getQuests().forEach(quest => result.push(quest));
    });
    return result;
  },

  completed(data, faction, questId) {
    return this.chapterQuests(faction).some(quest => String(quest.getCodeString()) === questId && data.isCompleted(quest));
  },

  // Managed worlds map parties to factions; older worlds use the charter the party already holds.
  factionOf(team) {
    if (!team || !team.isPartyTeam()) return null;
    if (typeof factionParties !== 'undefined' && factionParties.active()) {
      let faction = factionParties.faction(team);
      return faction && this.config.factions[faction.id] ? faction.id : null;
    }
    let data = this.ready() ? this.file().getNullableTeamData(team.getId()) : null;
    if (!data) return null;
    return Object.keys(this.config.factions).find(id => this.completed(data, id, this.config.factions[id].charterQuest)) || null;
  },

  // Charters: membership in managed worlds; an operator-granted faction stage in older worlds.
  playerFaction(player) {
    let team = this.teams().getTeamForPlayer(player).orElse(null);
    if (typeof factionParties !== 'undefined' && factionParties.active()) return this.factionOf(team);
    if (!team || !team.isPartyTeam()) return null;
    let match = factionDefinitions.factions.find(faction => this.config.factions[faction.id] && AStages.playerHasStage(player, faction.id));
    return match ? match.id : null;
  },

  earned(team) {
    let faction = this.factionOf(team);
    let data = faction ? this.file().getNullableTeamData(team.getId()) : null;
    if (!data) return 0;
    let values = this.config.factions[faction].quests;
    let total = 0;
    this.chapterQuests(faction).forEach(quest => {
      let value = values[String(quest.getCodeString())];
      if (value && data.isCompleted(quest)) total += value;
    });
    return Math.min(total, this.config.maxClaims - this.config.baseClaims);
  },

  // Personal bonus for a player's own team: their party's earned chunks, or 0 outside a party.
  // FTB Chunks only counts personal bonuses, so every member carries the party's value.
  bonusFor(team, cache) {
    if (!this.ready()) return null;
    let party = this.teams().getTeamForPlayerID(team.getOwner()).orElse(null);
    return party && party.isPartyTeam() ? this.partyBonus(party, cache) : 0;
  },

  partyBonus(party, cache) {
    if (!this.ready()) return null;
    let id = String(party.getId());
    if (!cache.has(id)) cache.set(id, this.earned(party));
    return cache.get(id);
  },

  status(source) {
    let player = source.getPlayerOrException();
    let party = this.teams().getTeamForPlayer(player).orElse(null);
    if (!party || !party.isPartyTeam() || !this.ready()) {
      source.sendSuccess(Text.of('You are not in a faction party. Unaffiliated players may claim ' + this.config.baseClaims + ' chunks.'), false);
      return 1;
    }
    let allowance = this.config.baseClaims + this.earned(party);
    let claimed = MilestoneChunks.api().getManager().getOrCreateData(party).getClaimedChunks().size();
    source.sendSuccess(Text.of(`${party.getName().getString()}: ${claimed} of ${allowance} chunks claimed `
      + `(base ${this.config.baseClaims}, maximum ${this.config.maxClaims}). Complete faction milestone quests to raise the allowance.`), false);
    return 1;
  },
};

Object.keys(factionMilestones.config.factions).forEach(faction => {
  let definition = factionMilestones.config.factions[faction];
  FTBQuestsEvents.customTask(definition.charterTask, event => {
    event.setCheckTimer(20);
    event.setCheck((task, player) => {
      if (factionMilestones.playerFaction(player) === faction) task.setProgress(1);
    });
  });
  FTBQuestsEvents.customTask(definition.homeTask, event => {
    event.setCheckTimer(40);
    event.setCheck((task, player) => {
      let party = factionSession.party(player);
      if (party && factionSession.home(player.server, party)) task.setProgress(1);
    });
  });
});

Object.keys(factionMilestones.config.rewards).forEach(id => {
  let reward = factionMilestones.config.rewards[id];
  FTBQuestsEvents.customReward(id, event => {
    let player = event.player;
    let party = factionMilestones.teams().getTeamForPlayer(player).orElse(null);
    if (!party || !party.isPartyTeam()) return;
    factionSession.normalizeLimits();
    let allowance = factionMilestones.config.baseClaims + factionMilestones.earned(party);
    party.getOnlineMembers().forEach(member => member.tell(Text.green(`Milestone reached: +${reward.chunks} claimed chunk`
      + `${reward.chunks === 1 ? '' : 's'}. ${party.getName().getString()} may now claim ${allowance} chunks.`)));
  });
});

ServerEvents.commandRegistry(event => {
  let commands = event.commands;
  event.register(commands.literal('faction').then(commands.literal('claims')
    .executes(context => factionSession.command(context.source, () => factionMilestones.status(context.source)))));
});
